"""`KK Nose`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = 'KK Nose'


def build(lib):
    t = lib.new_material(NAME, props={
            'surface_render_method': 'BLENDED',
            'blend_method': 'BLEND',
            'use_transparency_overlap': False,
            'show_transparent_back': False,
            'use_backface_culling': True,
            'use_backface_culling_lightprobe_volume': False,
            'preview_render_type': 'FLAT',
            'diffuse_color': (1.0, 1.0, 1.0, 1.0),
            'specular_color': (0.0, 0.0, 0.0),
            'roughness': 1.0,
            'line_color': (0.0, 0.0, 0.0, 1.0),
        })

    t.node('NodeFrame', 'Frame.001', props={
        'location': (-244.0, 78.75),
        'width': 292.406,
        'height': 214.74998,
        'label': 'Texture files',
        'use_custom_color': True,
        'color': (0.2901505, 0.6787529, 0.1812863),
        'label_size': 23,
    })
    t.node('NodeFrame', 'FrameInfo.001', props={
        'location': (110.0, 93.75),
        'width': 286.51675,
        'height': 214.75,
        'label': 'Shader',
        'use_custom_color': True,
        'color': (0.33001542, 0.4420454, 0.6247832),
        'label_size': 23,
    })
    t.node('NodeFrame', 'FrameInfo.002', props={
        'location': (440.0, 82.75),
        'width': 200.0,
        'height': 149.75,
        'label': 'Output',
        'use_custom_color': True,
        'color': (0.6247832, 0.073067226, 0.042191483),
        'label_size': 23,
    })
    t.node('ShaderNodeGroup', 'combine', parent='FrameInfo.001', inputs={'Toon shading': 1.0, 'Alpha mask': (1.0, 1.0, 1.0, 1.0), 'Alpha mask (alpha)': 1.0, 'Alpha mask (custom)': (1.0, 1.0, 1.0, 1.0), 'Force visibility': 0.0}, hide_inputs=('Toon shading', 'Alpha mask', 'Alpha mask (alpha)', 'Alpha mask (custom)', 'Force visibility', 'Force custom mask'), props={
        'node_tree': lib.group('.Combine colors'),
        'location': (30.363495, -43.589478),
        'width': 226.51675,
    })
    t.node('ShaderNodeOutputMaterial', 'out', parent='FrameInfo.002', hide_inputs=('Volume', 'Displacement', 'Thickness'), props={
        'location': (30.214508, -43.681152),
    })
    t.node('ShaderNodeGroup', 'textures', parent='Frame.001', hide_outputs=('Kage texture', 'Kage texture (alpha)', 'Toon shading'), props={
        'node_tree': lib.group('.Tex Face misc'),
        'location': (29.977844, -43.537827),
        'width': 232.40607,
    })

    t.link('combine', 'Result', 'out', 'Surface')
    t.link('textures', 'Main texture', 'combine', 'Light colors')
    t.link('textures', 'Main texture', 'combine', 'Dark colors')
    t.link('textures', 'Main texture (alpha)', 'combine', 'Main texture (alpha)')
    return t
